#!/usr/bin/env python3
"""
apply_STFC_SPOT_20260913.py — STFC_V1 v2: SL/TP tracked on the INDEX (spot
basis) with ORB-audited option fill conventions; premium basis kept.

FENCE: STFC_SPOT_20260913   (requires STFC_OPT_20260913 applied)

Replaces (backup .bak-FENCE)
  backend/app/backtest/stfc/stfc_v1_engine.py
  backend/app/backtest/stfc/backtest_stfc_runner.py
  backend/app/backtest/stfc/test_stfc_runner_sim.py
Patches (anchored inside the STFC_OPT_20260913 blocks)
  frontend/src/pages/Backtest.jsx      basis/trigger/fill state + LS + buildConfig + deps + form + describeConfig
  frontend/src/pages/backtest/paramFormat.js
  frontend/src/pages/backtest/SweepBuilder.jsx   (axis hints only)

Run from the repo root:  python3 apply_STFC_SPOT_20260913.py
"""
import os, sys, py_compile, shutil, subprocess, tempfile

FENCE = "STFC_SPOT_20260913"
PARENT = "STFC_OPT_20260913"
ROOT = os.path.abspath(os.getcwd())
BACKEND = os.path.join(ROOT, "backend")
FRONTEND = os.path.join(ROOT, "frontend")
DUAL_BACKEND = os.path.join(ROOT, "desktop", "src-tauri", "backend")
DUAL_FRONTEND = os.path.join(ROOT, "desktop", "src-tauri", "frontend")

ENGINE_SRC = '# backend/app/backtest/stfc/stfc_v1_engine.py\n#\n# ── STFC_V1 ENGINE ── "SuperTrend Flip-Confirm" signal core (pure, no I/O).\n#\n# Fence: STFC_OPT_20260913  (v2: STFC_SPOT_20260913 — spot levels)\n#\n# Port of the TradingView "ST Flip-Confirm Scalper v2" indicator and the\n# Crypto Lab engine (crypto_stfc_engine.py), kept in lock-step:\n#   D1  Bars: 1m SPOT resampled to `tf` minutes on the NSE session grid\n#       (buckets from 09:15, same as TradingView\'s NSE charts). A bar\'s\n#       end minute is recorded so "candle close" exits can land on it.\n#   D2  SuperTrend(len, mult) is a bit-for-bit port of Pine\'s ta.supertrend:\n#       ATR = RMA(TR) seeded with the SMA of the first `len` TRs, hl2 source,\n#       band ratcheting, direction −1 = up-trend / +1 = down-trend. The\n#       indicator state is CONTINUOUS across sessions (TradingView parity —\n#       the chart does not reset ATR at 09:15); the runner warms it up on\n#       sessions before date_from.\n#   D3  Setup machine, per tf bar, in Pine order:\n#         1. if armed by the previous bar → this bar is a TRADE bar\n#            (entry at its open = the 1m open of its first minute)\n#         2. flip on this bar → C1 is ignored; pending := new direction\n#         3. else pending and the bar\'s colour matches → arm the next bar\n#       A fresh flip while pending restarts the setup; a doji never\n#       confirms. The machine RESETS at each session open (no overnight\n#       carry — an arm on the last bar of a day is lost, counted by the\n#       runner).\n#   D4  Premium fills (pessimistic, same helper as ORB/CBO): a level touched\n#       inside a 1m bar books AT the level; gapped through at the open books\n#       the open.\n#\n# Fleet convention: no imports from sibling strategy packages; helpers are\n# duplicated here so the module stays self-contained.\n\nfrom __future__ import annotations\n\nfrom dataclasses import dataclass\nfrom typing import Dict, List, Optional, Tuple\n\nSESSION_OPEN_MIN = 9 * 60 + 15        # NSE index grid opens 09:15\n\n\n@dataclass(frozen=True)\nclass StfcBar:\n    ts: int                            # epoch seconds, bar START, IST grid\n    open: float\n    high: float\n    low: float\n    close: float\n    end_min: int = 0                   # minute-of-day of the bar\'s LAST 1m slot\n\n\n# ─────────────────────────────────────────────────────────────────────────\n#  RESAMPLE — session-aligned tf buckets from 09:15\n# ─────────────────────────────────────────────────────────────────────────\ndef resample_session(bars_1m, *, day_start_epoch: int, tf_minutes: int\n                     ) -> List[StfcBar]:\n    """bars_1m: objects with ts/open/high/low/close (1m, ascending)."""\n    out: Dict[int, dict] = {}\n    for b in bars_1m:\n        mod = (b.ts - day_start_epoch) // 60\n        if mod < SESSION_OPEN_MIN:\n            continue\n        bucket = (mod - SESSION_OPEN_MIN) // tf_minutes\n        bts = day_start_epoch + (SESSION_OPEN_MIN + bucket * tf_minutes) * 60\n        cur = out.get(bts)\n        if cur is None:\n            out[bts] = {"o": b.open, "h": b.high, "l": b.low, "c": b.close,\n                        "end": SESSION_OPEN_MIN + (bucket + 1) * tf_minutes - 1}\n        else:\n            cur["h"] = max(cur["h"], b.high)\n            cur["l"] = min(cur["l"], b.low)\n            cur["c"] = b.close\n    return [StfcBar(ts, v["o"], v["h"], v["l"], v["c"], v["end"])\n            for ts, v in sorted(out.items())]\n\n\n# ─────────────────────────────────────────────────────────────────────────\n#  SUPERTREND — stateful, TradingView-exact (D2)\n# ─────────────────────────────────────────────────────────────────────────\nclass SuperTrend:\n    def __init__(self, length: int, mult: float):\n        if length < 1:\n            raise ValueError("length must be >= 1")\n        self.length = int(length)\n        self.mult = float(mult)\n        self.n = 0                     # bars seen\n        self.tr_sum = 0.0\n        self.atr: Optional[float] = None\n        self.prev_close: Optional[float] = None\n        self.prev_upper = 0.0\n        self.prev_lower = 0.0\n        self.prev_st: Optional[float] = None\n        self.direction: Optional[int] = None\n\n    def update(self, b: StfcBar) -> Tuple[Optional[float], Optional[int]]:\n        h, l, c = b.high, b.low, b.close\n        tr = (h - l) if self.prev_close is None else max(\n            h - l, abs(h - self.prev_close), abs(l - self.prev_close))\n        atr_was_na = self.atr is None\n        if self.n < self.length - 1:\n            self.tr_sum += tr\n            atr = None\n        elif self.n == self.length - 1:\n            self.tr_sum += tr\n            atr = self.tr_sum / self.length\n        else:\n            atr = (self.atr * (self.length - 1) + tr) / self.length\n        self.n += 1\n        if atr is None:\n            self.prev_close = c\n            self.direction = None\n            return None, None\n        src = (h + l) / 2.0\n        upper = src + self.mult * atr\n        lower = src - self.mult * atr\n        pc = self.prev_close if self.prev_close is not None else c\n        lower = lower if (lower > self.prev_lower or pc < self.prev_lower) else self.prev_lower\n        upper = upper if (upper < self.prev_upper or pc > self.prev_upper) else self.prev_upper\n        if atr_was_na:\n            d = 1\n        elif self.prev_st == self.prev_upper:\n            d = -1 if c > upper else 1\n        else:\n            d = 1 if c < lower else -1\n        st = lower if d == -1 else upper\n        self.prev_upper, self.prev_lower, self.prev_st = upper, lower, st\n        self.atr = atr\n        self.prev_close = c\n        self.direction = d\n        return st, d\n\n\n# ─────────────────────────────────────────────────────────────────────────\n#  SETUP MACHINE (D3)\n# ─────────────────────────────────────────────────────────────────────────\n@dataclass(frozen=True)\nclass StfcSignal:\n    bar_index: int                     # index of the TRADE bar in the day\'s list\n    side: str                          # CE (up-flip) | PE (down-flip)\n    flip_index: int\n    confirm_index: int\n\n\ndef session_signals(bars: List[StfcBar], dirs: List[Optional[int]], *,\n                    direction: str = "BOTH", diag: Optional[dict] = None\n                    ) -> List[StfcSignal]:\n    """One session\'s signals. `dirs[i]` is the SuperTrend direction after\n    bar i (None while warming up). The machine starts flat; the previous\n    session\'s arm never carries over."""\n    out: List[StfcSignal] = []\n    pend = 0\n    armed = False\n    armed_side = ""\n    flip_i = -1\n    prev_d: Optional[int] = None\n    want_up = direction in ("BOTH", "UP")\n    want_dn = direction in ("BOTH", "DOWN")\n    for i, b in enumerate(bars):\n        if armed:\n            out.append(StfcSignal(i, armed_side, flip_i, i - 1))\n        armed = False\n        d = dirs[i]\n        if d is None or prev_d is None:\n            prev_d = d\n            continue\n        is_up, was_up = d < 0, prev_d < 0\n        prev_d = d\n        flip_up = is_up and not was_up\n        flip_dn = (not is_up) and was_up\n        if flip_up or flip_dn:\n            if diag is not None:\n                diag["flips_up" if flip_up else "flips_dn"] = \\\n                    diag.get("flips_up" if flip_up else "flips_dn", 0) + 1\n            pend = (1 if want_up else 0) if flip_up else (-1 if want_dn else 0)\n            flip_i = i\n            continue\n        green = b.close > b.open\n        red = b.close < b.open\n        if pend == 1 and green:\n            armed, armed_side, pend = True, "CE", 0\n        elif pend == -1 and red:\n            armed, armed_side, pend = True, "PE", 0\n    if armed and diag is not None:\n        diag["arm_lost_eod"] = diag.get("arm_lost_eod", 0) + 1\n    return out\n\n\n# ─────────────────────────────────────────────────────────────────────────\n#  PREMIUM LEVELS & FILLS (D4)\n# ─────────────────────────────────────────────────────────────────────────\ndef prem_level(entry_px: float, mode: str, value: float, *, is_stop: bool\n               ) -> Optional[float]:\n    if mode == "off" or value <= 0:\n        return None\n    dist = value if mode == "abs" else entry_px * value / 100.0\n    lvl = entry_px - dist if is_stop else entry_px + dist\n    return max(0.05, lvl)\n\n\ndef prem_fill(*, level: float, bar, side_is_stop: bool) -> Optional[float]:\n    """Fill for a PREMIUM level on the option\'s 1m bar, or None if untouched.\n    Gapped through at the open → the open; otherwise the level."""\n    if side_is_stop:\n        if bar.open <= level:\n            return float(bar.open)\n        return level if bar.low <= level else None\n    if bar.open >= level:\n        return float(bar.open)\n    return level if bar.high >= level else None\n\n\n# ─────────────────────────────────────────────────────────────────────────\n#  SPOT LEVELS & BREACH (STFC_SPOT_20260913) — CE is long spot, PE short\n# ─────────────────────────────────────────────────────────────────────────\ndef spot_level(entry_spot: float, side: str, mode: str, value: float, *,\n               is_stop: bool) -> Optional[float]:\n    """mode abs = index points, pct = % of entry spot. Stop is against the\n    position (CE below / PE above), target is with it."""\n    if mode == "off" or value <= 0:\n        return None\n    dist = value if mode == "abs" else entry_spot * value / 100.0\n    sign = 1.0 if side == "CE" else -1.0\n    return entry_spot - sign * dist if is_stop else entry_spot + sign * dist\n\n\ndef spot_breached(side: str, level: float, bar, *, is_stop: bool,\n                  trigger: str = "touch") -> bool:\n    """Did this 1m SPOT bar cross `level` in the direction that fires it?\n    touch = the bar\'s low/high tags it; close = the bar CLOSES through."""\n    # CE stop / PE target are BELOW; CE target / PE stop are ABOVE.\n    below = (side == "CE") == is_stop\n    if trigger == "close":\n        return bar.close <= level if below else bar.close >= level\n    return bar.low <= level if below else bar.high >= level\n\n\ndef strike_step(strikes) -> float:\n    """Smallest positive gap between distinct strikes (50 NIFTY / 100 BNF)."""\n    s = sorted({float(x) for x in strikes if x is not None})\n    gaps = [b - a for a, b in zip(s, s[1:]) if b - a > 0]\n    return min(gaps) if gaps else 50.0\n\n\ndef atm_strike(spot: float, step: float) -> float:\n    return round(spot / step) * step\n'
RUNNER_SRC = '# backend/app/backtest/stfc/backtest_stfc_runner.py\n#\n# ── STFC_V1 RUNNER ── "SuperTrend Flip-Confirm" on NIFTY/BANKNIFTY SPOT\n# with weekly option BUY execution and premium-denominated exits.\n#\n# Fence: STFC_OPT_20260913  (v2: STFC_SPOT_20260913 — spot-basis exits)\n#\n# Engine decisions D1–D4 in stfc_v1_engine.py. Runner-owned decisions:\n#   R1  Entry fill: a trade bar (engine D3) starts at minute M; the option\n#       fills at M\'s 1m OPEN. entry_spot = SPOT 1m open at M. No unfinished-\n#       bar reads: the confirm bar has fully closed before M.\n#   R2  Contract: ATM strike from entry_spot (step inferred from the day\'s\n#       chain) shifted `strike_offset` steps OUT of the money (negative =\n#       in the money), expected weekly expiry only, same side as the flip\n#       (up-flip → CE, down-flip → PE). If that strike has no print at M\n#       the nearest strike with a print is used (counted). Optional\n#       premium band {min,max} rejects absurd fills (0 = off).\n#   R3  Exits, evaluated per minute in this order (pessimistic — stop\n#       before target, both before time). exit_basis selects the level:\n#       "premium" (default v1):\n#         1. PREMIUM stop  (sl_mode off|abs|pct of entry premium) → books\n#            AT the level (open if gapped through).\n#         2. PREMIUM target (tp_mode off|abs|pct) → books AT the level.\n#       "spot" (STFC_SPOT_20260913 — the TradingView test\'s semantics):\n#         1. SPOT stop (abs = index points | pct of entry spot; CE below /\n#            PE above entry_spot). Trigger "touch" (1m low/high) books on\n#            the OPTION\'s own 1m bar that minute — spot_sl_fill "low"\n#            (default, pessimistic bound on a spot-triggered market sell)\n#            or "close" (legacy). Trigger "close" sells at the NEXT\n#            minute\'s option open (wick-immune, ORB_SLTRIG convention).\n#         2. SPOT target (CE above / PE below) → spot_tp_fill "close"\n#            (default), "high" (optimistic) or "low" (stress) of the\n#            option\'s bar that minute; close-trigger → next open.\n#         3. TIME: exit_mode "candle" → the 1m CLOSE of the trade bar\'s\n#            last minute (the Pine "exit at candle close"); "minutes" →\n#            the 1m CLOSE of the minute completing hold_minutes from entry\n#            (may span several tf bars).\n#         4. EOD square-off at the option 1m close.\n#       A missing option bar leaves the last mark in place (counted).\n#   R4  Budgets: one position at a time — a signal that fires while in a\n#       position is SKIPPED, never queued (counted); max_trades_per_day\n#       (0 = unlimited); no entries at/after entry_block_time.\n#   R5  SuperTrend state is continuous across sessions and warmed up on\n#       `warmup_sessions` sessions before date_from (no trades there).\n#\n# ── FALSIFICATION TRIPWIRES ─────────────────────────────────────────────\n#   * time/candle_pnl_share_pct vs sl/tp — if the timed exit carries the\n#     net, the edge is "hold N minutes after a flip", not the SL/TP shape.\n#   * sig_dropped_open — with long holds most signals are skipped; the\n#     run then describes a much sparser strategy than the chart suggests.\n#   * eod_pnl_share_pct — should be ~0 with short holds.\n#   * ce_net vs pe_net and the DTE breakdown — 0DTE premium decay inside\n#     the hold is the first thing that can kill this.\n\nfrom __future__ import annotations\n\nimport uuid\nfrom dataclasses import dataclass, field\nfrom datetime import date, datetime, timedelta\nfrom typing import Callable, Dict, List, Optional\n\ntry:\n    from app.backtest.stfc.stfc_v1_engine import (\n        StfcBar, SuperTrend, resample_session, session_signals,\n        prem_level, prem_fill, spot_level, spot_breached, strike_step,\n        atm_strike, SESSION_OPEN_MIN)\nexcept ImportError:                                        # standalone tests\n    from stfc_v1_engine import (  # type: ignore\n        StfcBar, SuperTrend, resample_session, session_signals,\n        prem_level, prem_fill, spot_level, spot_breached, strike_step,\n        atm_strike, SESSION_OPEN_MIN)\n\nIST_OFFSET = 5 * 3600 + 30 * 60\nINDEX_LOTS = {"NIFTY": 65, "BANKNIFTY": 35}\n\nDEFAULTS: dict = {\n    # ── signal (D1/D2/D3) ──\n    "timeframe_minutes": 3,\n    "st_len": 10,\n    "st_mult": 2.0,\n    "direction": "BOTH",               # BOTH | UP | DOWN\n    "warmup_sessions": 3,\n\n    # ── contract (R2) ──\n    "strike_offset": 0,                # steps OTM (negative = ITM)\n    "premium_min": 0.0,                # 0 = off\n    "premium_max": 0.0,                # 0 = off\n    "lots": 1,\n    "lot_size": 0,                     # 0 = index constant\n\n    # ── exits (R3) ──\n    "exit_basis": "spot",              # premium | spot   ── STFC_SPOT_20260913 ──\n    "sl_mode": "pct",                  # off | abs | pct (premium: ₹/% of entry premium; spot: pts/% of entry spot)\n    "sl_value": 0.1,\n    "tp_mode": "pct",                  # off | abs | pct\n    "tp_value": 0.3,\n    "spot_sl_trigger": "touch",        # touch | close      (spot basis only)\n    "spot_sl_fill": "low",             # low | close        (touch trigger only)\n    "spot_tp_fill": "close",           # close | high | low (touch trigger only)\n    "exit_mode": "candle",             # candle | minutes\n    "hold_minutes": 5,\n    "eod_square_off": "15:20",\n\n    # ── budgets & session (R4) ──\n    "entry_block_time": "15:00",\n    "max_trades_per_day": 0,           # 0 = unlimited\n    "skip_expiry_day": False,\n}\n\n\n@dataclass\nclass STFCTrade:\n    """persist_run-compatible attribute surface (object, no hedge_symbol)."""\n    tradingsymbol: str\n    symbol: str\n    instrument_type: str\n    strike: Optional[float]\n    expiry: Optional[str]\n    direction: str                     # always BUY\n    entry_ts: int\n    entry_price: float\n    sl: Optional[float]                # stop level (premium or spot per exit_basis)\n    tp: Optional[float]                # target level (premium or spot per exit_basis)\n    exit_ts: Optional[int]\n    exit_price: Optional[float]\n    exit_reason: Optional[str]         # SL | TP | TIME | CANDLE | EOD\n    qty: int\n    condition: str\n    ambiguous_fill: bool = False\n    pnl: float = 0.0\n    charges: float = 0.0\n    net_pnl: float = 0.0\n    max_adverse: Optional[float] = None\n    max_favorable: Optional[float] = None\n    gross: float = field(default=0.0)\n    net: float = field(default=0.0)\n    ambiguous: bool = field(default=False)\n    synthetic: bool = field(default=False)\n    synth_kind: Optional[str] = field(default=None)\n    entry_spot: Optional[float] = None\n    hold_min: int = 0\n\n\ndef _empty_summary() -> dict:\n    return {"total_trades": 0, "wins": 0, "losses": 0, "win_rate": 0.0,\n            "gross_pnl": 0.0, "total_charges": 0.0, "net_pnl": 0.0,\n            "max_drawdown": 0.0, "ambiguous_fills": 0}\n\n\ndef _hhmm(s: str, fallback: int) -> int:\n    try:\n        h, m = str(s).split(":")\n        v = int(h) * 60 + int(m)\n        return v if 0 <= v < 24 * 60 else fallback\n    except (ValueError, AttributeError):\n        return fallback\n\n\ndef _day_start_epoch(d: date) -> int:\n    return int((datetime(d.year, d.month, d.day)\n                - datetime(1970, 1, 1)).total_seconds()) - IST_OFFSET\n\n\ndef _merge_cfg(override: Optional[dict]) -> dict:\n    cfg = dict(DEFAULTS)\n    for k, v in (override or {}).items():\n        cfg[k] = v\n    _d = str(cfg.get("direction", "BOTH")).upper()\n    cfg["direction"] = _d if _d in ("BOTH", "UP", "DOWN") else "BOTH"\n    for k in ("sl_mode", "tp_mode"):\n        m = str(cfg.get(k, "off")).lower()\n        cfg[k] = m if m in ("off", "abs", "pct") else "off"\n    cfg["exit_mode"] = ("minutes" if str(cfg.get("exit_mode", "candle")\n                                         ).lower() == "minutes" else "candle")\n    # ── STFC_SPOT_20260913 ── a saved v1 config (has st_len but no\n    # exit_basis) reproduces as PREMIUM basis; a blank override takes the\n    # new default (spot); anything explicit wins.\n    if "exit_basis" in (override or {}):\n        cfg["exit_basis"] = "spot" if str(override["exit_basis"]).lower() == "spot" else "premium"\n    elif override and "st_len" in override:\n        cfg["exit_basis"] = "premium"\n    else:\n        cfg["exit_basis"] = DEFAULTS["exit_basis"]\n    cfg["spot_sl_trigger"] = ("close" if str(cfg.get("spot_sl_trigger", "touch")).lower() == "close" else "touch")\n    cfg["spot_sl_fill"] = ("close" if str(cfg.get("spot_sl_fill", "low")).lower() == "close" else "low")\n    _tf = str(cfg.get("spot_tp_fill", "close")).lower()\n    cfg["spot_tp_fill"] = _tf if _tf in ("close", "high", "low") else "close"\n    for k in ("timeframe_minutes", "st_len", "hold_minutes", "warmup_sessions",\n              "max_trades_per_day", "lots", "lot_size"):\n        try:\n            cfg[k] = max(0, int(cfg[k] or 0))\n        except (TypeError, ValueError):\n            cfg[k] = int(DEFAULTS[k])\n    try:\n        cfg["strike_offset"] = int(cfg.get("strike_offset") or 0)\n    except (TypeError, ValueError):\n        cfg["strike_offset"] = 0\n    for k in ("st_mult", "sl_value", "tp_value", "premium_min", "premium_max"):\n        try:\n            cfg[k] = abs(float(cfg[k] or 0.0))\n        except (TypeError, ValueError):\n            cfg[k] = float(DEFAULTS[k])\n    cfg["lots"] = cfg["lots"] or 1\n    cfg["timeframe_minutes"] = cfg["timeframe_minutes"] or 3\n    cfg["st_len"] = cfg["st_len"] or 10\n    cfg["st_mult"] = cfg["st_mult"] or 2.0\n    cfg["hold_minutes"] = cfg["hold_minutes"] or 5\n    cfg["skip_expiry_day"] = bool(cfg.get("skip_expiry_day", False))\n    from app.backtest.engine.dte_lots import parse_dte_lot_mult   # ── DTE_LOT_MULT_20260911 ──\n    cfg["dte_lot_mult"] = parse_dte_lot_mult(cfg.get("dte_lot_mult"))\n    return cfg\n\n\ndef run_stfc_backtest(\n    *, db_path: str, strategy_id: str, underlying: str,\n    date_from: date, date_to: date,\n    config_override: Optional[dict] = None,\n    progress_cb: Optional[Callable[[dict], None]] = None,\n    cancel_cb: Optional[Callable[[], bool]] = None,\n) -> Dict:\n    try:\n        from app.event_bus.audit_logger import audit_muted\n        with audit_muted():\n            return _impl(db_path=db_path, strategy_id=strategy_id,\n                         underlying=underlying, date_from=date_from,\n                         date_to=date_to, config_override=config_override,\n                         progress_cb=progress_cb, cancel_cb=cancel_cb)\n    except ImportError:\n        return _impl(db_path=db_path, strategy_id=strategy_id,\n                     underlying=underlying, date_from=date_from,\n                     date_to=date_to, config_override=config_override,\n                     progress_cb=progress_cb, cancel_cb=cancel_cb)\n\n\ndef _abort(cfg, strategy_id, reason) -> Dict:\n    return {"run_id": None, "aborted": True, "reason": reason,\n            "trades": [], "summary": _empty_summary(),\n            "config": cfg, "strategy_id": strategy_id}\n\n\ndef pick_contract(universe: List[dict], side: str, *, target_strike: float,\n                  has_print) -> tuple:\n    """R2: the side\'s contract at target_strike with a print at the entry\n    minute; else the nearest strike that has one. Returns (contract, fallback)."""\n    cands = [c for c in universe\n             if c.get("instrument_type") == side and c.get("strike") is not None]\n    exact = [c for c in cands if float(c["strike"]) == target_strike]\n    for c in exact:\n        if has_print(c["tradingsymbol"]):\n            return c, False\n    best = None\n    for c in sorted(cands, key=lambda x: (abs(float(x["strike"]) - target_strike),\n                                          float(x["strike"]))):\n        if has_print(c["tradingsymbol"]):\n            best = c\n            break\n    return best, True\n\n\ndef _impl(*, db_path, strategy_id, underlying, date_from, date_to,\n          config_override, progress_cb, cancel_cb) -> Dict:\n    from app.backtest.data.candle_source import CandleSource\n    from app.backtest.engine.expiry_calendar import expected_expiry_for_day\n    from app.backtest.charges.charges_model import charges_for_long_trade\n    from app.backtest.util.lot_sizes import resolve_lot\n    from app.utils.market_hours import is_trading_day\n    from app.event_bus.audit_logger import write_audit_log\n\n    cfg = _merge_cfg(config_override)\n\n    index_lot = INDEX_LOTS.get(underlying.upper())\n    if index_lot is None:\n        return _abort(cfg, strategy_id,\n                      f"STFC_V1 is index-only; no lot constant for {underlying}.")\n    lot_size, lot_source = resolve_lot(\n        underlying=underlying, is_stock=False, cfg_lot=cfg["lot_size"],\n        index_lot=index_lot, db_path=db_path)\n    if lot_size is None:\n        return _abort(cfg, strategy_id, f"no lot size for {underlying}")\n    qty = cfg["lots"] * lot_size\n\n    tf = cfg["timeframe_minutes"]\n    block_min = _hhmm(cfg["entry_block_time"], 15 * 60)\n    eod_min = _hhmm(cfg["eod_square_off"], 15 * 60 + 20)\n    if not (SESSION_OPEN_MIN < block_min <= eod_min <= 15 * 60 + 29):\n        return _abort(cfg, strategy_id,\n                      f"time order must be 09:15 < entry_block_time "\n                      f"{cfg[\'entry_block_time\']} <= eod_square_off "\n                      f"{cfg[\'eod_square_off\']} <= 15:29")\n    if not (1 <= tf <= 60):\n        return _abort(cfg, strategy_id, "timeframe_minutes must be 1..60")\n    if not (2 <= cfg["st_len"] <= 200):\n        return _abort(cfg, strategy_id, "st_len must be 2..200")\n    if not (0.1 <= cfg["st_mult"] <= 20):\n        return _abort(cfg, strategy_id, "st_mult must be 0.1..20")\n    for k in ("sl", "tp"):\n        if cfg[f"{k}_mode"] != "off" and cfg[f"{k}_value"] <= 0:\n            return _abort(cfg, strategy_id, f"{k}_mode {cfg[f\'{k}_mode\']} needs {k}_value > 0")\n        if cfg[f"{k}_mode"] == "pct" and cfg[f"{k}_value"] > 100:\n            return _abort(cfg, strategy_id,\n                          f"{k}_value {cfg[f\'{k}_value\']} in pct mode looks like rupees")\n        # ── STFC_SPOT_20260913 ── footgun guards: a premium-scale number\n        # left behind after switching the basis must ABORT, never run.\n        if cfg["exit_basis"] == "spot" and cfg[f"{k}_mode"] == "pct" and cfg[f"{k}_value"] > 5:\n            return _abort(cfg, strategy_id,\n                          f"spot basis: {k}_value {cfg[f\'{k}_value\']}% of spot looks like a "\n                          f"premium % — use <= 5 (0.1 = 24 pts on a 24,000 index)")\n        if cfg["exit_basis"] == "spot" and cfg[f"{k}_mode"] == "abs" and cfg[f"{k}_value"] < 1:\n            return _abort(cfg, strategy_id,\n                          f"spot basis: {k}_value {cfg[f\'{k}_value\']} points is below 1 — "\n                          f"did you mean pct?")\n    if cfg["exit_mode"] == "minutes" and not (1 <= cfg["hold_minutes"] <= 375):\n        return _abort(cfg, strategy_id, "hold_minutes must be 1..375")\n    if cfg["premium_max"] > 0 and cfg["premium_min"] >= cfg["premium_max"]:\n        return _abort(cfg, strategy_id, "premium band needs min < max")\n    if abs(cfg["strike_offset"]) > 10:\n        return _abort(cfg, strategy_id, "strike_offset must be within ±10 steps")\n\n    src = CandleSource(db_path)\n    conn = src._conn()\n\n    def spot_day(ds: int) -> list:\n        return [StfcBar(r["ts"], r["open"], r["high"], r["low"], r["close"])\n                for r in conn.execute(\n                    """SELECT ts, open, high, low, close FROM backtest_candles_1m\n                       WHERE underlying=? AND instrument_type=\'SPOT\'\n                         AND ts>=? AND ts<? ORDER BY ts""",\n                    (underlying, ds, ds + 86400))]\n\n    days: List[date] = []\n    d = date_from\n    while d <= date_to:\n        if is_trading_day(d):\n            days.append(d)\n        d += timedelta(days=1)\n\n    # ── R5: warm the SuperTrend on sessions before date_from ──\n    st = SuperTrend(cfg["st_len"], cfg["st_mult"])\n    warm_days: List[date] = []\n    d = date_from - timedelta(days=1)\n    guard = 0\n    while len(warm_days) < cfg["warmup_sessions"] and guard < 30:\n        if is_trading_day(d):\n            warm_days.append(d)\n        d -= timedelta(days=1)\n        guard += 1\n    warmup_bars = 0\n    for wd in reversed(warm_days):\n        for b in resample_session(spot_day(_day_start_epoch(wd)),\n                                  day_start_epoch=_day_start_epoch(wd), tf_minutes=tf):\n            st.update(b)\n            warmup_bars += 1\n\n    trades: List[STFCTrade] = []\n    diag = {\n        "days_total": len(days), "days_traded": 0, "days_no_spot": 0,\n        "days_uncovered": 0, "days_skipped_expiry": 0, "days_no_signal": 0,\n        # ── DTE_LOT_MULT_20260911 ──\n        "dte_lot_mult": {str(k): v for k, v in cfg["dte_lot_mult"].items()},\n        "dte_skipped_days": 0, "dte_scaled_days": 0, "dte_unknown_days": 0,\n        "warmup_bars": warmup_bars, "tf_bars": 0,\n        "flips_up": 0, "flips_dn": 0, "arm_lost_eod": 0,\n        "signals_total": 0,\n        "sig_dropped_open": 0, "sig_dropped_budget": 0,\n        "sig_dropped_block_time": 0, "sig_no_spot_bar": 0,\n        "sig_no_candidate": 0, "sig_no_fill": 0, "sig_band_reject": 0,\n        "strike_fallbacks": 0,\n        "exit_basis": cfg["exit_basis"], "eff_sl_sum": 0.0, "eff_tp_sum": 0.0,   # ── STFC_SPOT_20260913 ──\n        "entries": 0, "ce_entries": 0, "pe_entries": 0,\n        "ce_net": 0.0, "pe_net": 0.0, "entry_hour_hist": {},\n        "sl_exits": 0, "tp_exits": 0, "time_exits": 0, "candle_exits": 0,\n        "eod_exits": 0,\n        "sl_pnl_gross": 0.0, "tp_pnl_gross": 0.0, "time_pnl_gross": 0.0,\n        "candle_pnl_gross": 0.0, "eod_pnl_gross": 0.0,\n        "hold_sum": 0, "stale_marks": 0,\n        "underlying": underlying, "lot_size": lot_size,\n        "lot_source": lot_source, "qty": qty,\n        "corpus_db": str(db_path).rsplit("/", 1)[-1],\n    }\n\n    def close_trade(pos: dict, ts: int, px: float, reason: str) -> None:\n        gross = (px - pos["entry_px"]) * pos["qty"]\n        ch = charges_for_long_trade(entry_price=pos["entry_px"],\n                                    exit_price=px, qty=pos["qty"]).total_charges\n        net = gross - ch\n        t = pos["trade"]\n        t.exit_ts, t.exit_price, t.exit_reason = ts, round(px, 2), reason\n        t.pnl = t.gross = round(gross, 2)\n        t.charges = round(ch, 2)\n        t.net_pnl = t.net = round(net, 2)\n        t.max_adverse = round(pos["mae"], 2)\n        t.max_favorable = round(pos["mfe"], 2)\n        t.hold_min = int((ts - t.entry_ts) // 60) + 1\n        key = reason.lower()\n        diag[f"{key}_exits"] += 1\n        diag[f"{key}_pnl_gross"] += round(net, 2)\n        diag["hold_sum"] += t.hold_min\n        diag["ce_net" if t.instrument_type == "CE" else "pe_net"] += round(net, 2)\n\n    # ── DTE_LOT_MULT_20260911 ── corpus trading-day calendar (sessions)\n    _dte_cal: List[str] = []\n    if cfg["dte_lot_mult"]:\n        from app.backtest.repo.trading_calendar import trading_dates as _td\n        _dte_cal = _td(underlying, db_path)\n        if not _dte_cal:\n            write_audit_log(f"[BACKTEST][{strategy_id}] dte_lot_mult set but the "\n                            f"corpus calendar is empty — multiplier ignored")\n    from app.backtest.engine.dte_lots import lots_for_day as _lots_for_day, dte_for_day as _dte_for_day\n\n    for i, day in enumerate(days):\n        if cancel_cb and cancel_cb():\n            break\n        if progress_cb:\n            progress_cb({"day": i + 1, "total_days": len(days),\n                         "date": day.isoformat(), "trades": len(trades)})\n\n        ds = _day_start_epoch(day)\n        want = expected_expiry_for_day(day).isoformat()\n        spot_1m = spot_day(ds)\n        if not spot_1m:\n            diag["days_no_spot"] += 1\n            continue\n        spot_by_min = {(b.ts - ds) // 60: b for b in spot_1m}\n        bars_tf = resample_session(spot_1m, day_start_epoch=ds, tf_minutes=tf)\n        diag["tf_bars"] += len(bars_tf)\n        # the indicator ALWAYS advances (R5), even on days we do not trade\n        dirs = [st.update(b)[1] for b in bars_tf]\n\n        if cfg["skip_expiry_day"] and date.fromisoformat(want) == day:\n            diag["days_skipped_expiry"] += 1\n            continue\n        day_qty = qty\n        if cfg["dte_lot_mult"]:\n            _dte = _dte_for_day(_dte_cal, day.isoformat(), want) if _dte_cal else None\n            _lots, _tag = _lots_for_day(cfg["lots"], cfg["dte_lot_mult"], _dte)\n            if _tag == "skip":\n                diag["dte_skipped_days"] += 1\n                continue\n            if _tag == "scaled":\n                diag["dte_scaled_days"] += 1\n            elif _tag == "unknown":\n                diag["dte_unknown_days"] += 1\n            day_qty = _lots * lot_size\n\n        sm: dict = {}\n        sigs = session_signals(bars_tf, dirs, direction=cfg["direction"], diag=sm)\n        for k in ("flips_up", "flips_dn", "arm_lost_eod"):\n            diag[k] += sm.get(k, 0)\n        if not sigs:\n            diag["days_no_signal"] += 1\n            continue\n        diag["signals_total"] += len(sigs)\n\n        universe = src.contracts_active_on_day(underlying, ds, expiry=want)\n        if not universe:\n            diag["days_uncovered"] += 1\n            continue\n        step = strike_step([c.get("strike") for c in universe])\n        bars_by_sym: Dict[str, Dict[int, object]] = {}\n\n        def bars(sym: str) -> Dict[int, object]:\n            if sym not in bars_by_sym:\n                bars_by_sym[sym] = {c.ts: c for c in\n                                    src.candles_1m_for_symbol_day(sym, ds)}\n            return bars_by_sym[sym]\n\n        day_trades = 0\n        open_until: Optional[int] = None\n        traded = False\n\n        for s in sigs:\n            tb = bars_tf[s.bar_index]\n            entry_min = (tb.ts - ds) // 60                 # R1: trade bar\'s first minute\n            if open_until is not None and entry_min <= open_until:\n                diag["sig_dropped_open"] += 1\n                continue\n            if cfg["max_trades_per_day"] and day_trades >= cfg["max_trades_per_day"]:\n                diag["sig_dropped_budget"] += 1\n                continue\n            if entry_min >= block_min or entry_min >= eod_min:\n                diag["sig_dropped_block_time"] += 1\n                continue\n            sb = spot_by_min.get(entry_min)\n            if sb is None:\n                diag["sig_no_spot_bar"] += 1\n                continue\n            entry_spot = float(sb.open)\n            fill_ts = ds + entry_min * 60\n            sign = 1 if s.side == "CE" else -1\n            target_strike = atm_strike(entry_spot, step) + sign * cfg["strike_offset"] * step\n\n            def has_print(sym: str) -> bool:\n                b = bars(sym).get(fill_ts)\n                return b is not None and bool(b.open)\n\n            mc, fallback = pick_contract(universe, s.side,\n                                         target_strike=target_strike, has_print=has_print)\n            if mc is None:\n                diag["sig_no_candidate"] += 1\n                continue\n            if fallback:\n                diag["strike_fallbacks"] += 1\n            sym = mc["tradingsymbol"]\n            fb = bars(sym).get(fill_ts)\n            if fb is None or not fb.open:\n                diag["sig_no_fill"] += 1\n                continue\n            entry_px = float(fb.open)\n            if (cfg["premium_max"] > 0 and entry_px >= cfg["premium_max"]) or \\\n               (cfg["premium_min"] > 0 and entry_px < cfg["premium_min"]):\n                diag["sig_band_reject"] += 1\n                continue\n            spot_basis = cfg["exit_basis"] == "spot"\n            sl_prem = tp_prem = sl_spot = tp_spot = None\n            if spot_basis:\n                # ── STFC_SPOT_20260913 ── levels on the INDEX; CE is long\n                # spot, PE is short spot.\n                sl_spot = spot_level(entry_spot, s.side, cfg["sl_mode"], cfg["sl_value"], is_stop=True)\n                tp_spot = spot_level(entry_spot, s.side, cfg["tp_mode"], cfg["tp_value"], is_stop=False)\n                if sl_spot is not None:\n                    diag["eff_sl_sum"] += abs(entry_spot - sl_spot)\n                if tp_spot is not None:\n                    diag["eff_tp_sum"] += abs(tp_spot - entry_spot)\n            else:\n                sl_prem = prem_level(entry_px, cfg["sl_mode"], cfg["sl_value"], is_stop=True)\n                tp_prem = prem_level(entry_px, cfg["tp_mode"], cfg["tp_value"], is_stop=False)\n            hh, mm = entry_min // 60, entry_min % 60\n            _b = "s" if spot_basis else ""\n            sl_tag = ("SLoff" if (sl_prem is None and sl_spot is None) else\n                      f"{_b}SL{\'P\' if cfg[\'sl_mode\'] == \'pct\' else \'A\'}{cfg[\'sl_value\']:g}")\n            tp_tag = ("TPoff" if (tp_prem is None and tp_spot is None) else\n                      f"{_b}TP{\'P\' if cfg[\'tp_mode\'] == \'pct\' else \'A\'}{cfg[\'tp_value\']:g}")\n            if spot_basis and cfg["spot_sl_trigger"] == "close":\n                sl_tag += "@close"\n            ex_tag = (f"hold{cfg[\'hold_minutes\']}m" if cfg["exit_mode"] == "minutes"\n                      else "candle")\n            t = STFCTrade(\n                tradingsymbol=sym, symbol=sym, instrument_type=s.side,\n                strike=float(mc["strike"]) if mc.get("strike") is not None else None,\n                expiry=mc.get("expiry"), direction="BUY",\n                entry_ts=fill_ts, entry_price=round(entry_px, 2),\n                sl=(round(sl_spot, 2) if spot_basis else round(sl_prem, 2)) if (sl_spot if spot_basis else sl_prem) is not None else None,\n                tp=(round(tp_spot, 2) if spot_basis else round(tp_prem, 2)) if (tp_spot if spot_basis else tp_prem) is not None else None,\n                exit_ts=None, exit_price=None, exit_reason=None, qty=day_qty,\n                entry_spot=round(entry_spot, 2),\n                condition=(f"STFC·{s.side}·{hh:02d}:{mm:02d}·{tf}m·ST{cfg[\'st_len\']},"\n                           f"{cfg[\'st_mult\']:g}·{sl_tag}·{tp_tag}·{ex_tag}"\n                           f"{\'·FB\' if fallback else \'\'}"))\n            trades.append(t)\n            diag["entries"] += 1\n            diag["ce_entries" if s.side == "CE" else "pe_entries"] += 1\n            hk = f"{hh:02d}"\n            diag["entry_hour_hist"][hk] = diag["entry_hour_hist"].get(hk, 0) + 1\n            day_trades += 1\n            traded = True\n\n            pos = {"trade": t, "entry_px": entry_px, "qty": day_qty,\n                   "mae": 0.0, "mfe": 0.0, "last_mark": entry_px}\n            ob = bars(sym)\n            exit_min = eod_min\n            # R3 time boundary: candle mode → trade bar\'s last minute;\n            # minutes mode → the minute completing hold_minutes from entry\n            if cfg["exit_mode"] == "minutes":\n                time_min = entry_min + cfg["hold_minutes"] - 1\n                time_reason = "TIME"\n            else:\n                time_min = tb.end_min\n                time_reason = "CANDLE"\n\n            for m in range(entry_min, eod_min + 1):\n                o = ob.get(ds + m * 60)\n                if m >= eod_min:\n                    px = float(o.close) if o is not None else pos["last_mark"]\n                    close_trade(pos, ds + m * 60, px, "EOD")\n                    exit_min = m\n                    break\n                if o is not None:\n                    pos["last_mark"] = float(o.close)\n                    pos["mae"] = min(pos["mae"], (float(o.low) - entry_px) * day_qty)\n                    pos["mfe"] = max(pos["mfe"], (float(o.high) - entry_px) * day_qty)\n                else:\n                    diag["stale_marks"] += 1\n                if spot_basis:\n                    # ── STFC_SPOT_20260913 ── spot-level exits; the option\n                    # fill is a CONVENTION (no premium print of its own).\n                    b = spot_by_min.get(m)\n                    if b is not None:\n                        hit = None\n                        if sl_spot is not None and spot_breached(\n                                s.side, sl_spot, b, is_stop=True, trigger=cfg["spot_sl_trigger"]):\n                            hit = "SL"\n                        elif tp_spot is not None and spot_breached(\n                                s.side, tp_spot, b, is_stop=False, trigger=cfg["spot_sl_trigger"]):\n                            hit = "TP"\n                        if hit is not None:\n                            if cfg["spot_sl_trigger"] == "close":\n                                m2 = min(m + 1, eod_min)\n                                o2 = ob.get(ds + m2 * 60)\n                                px = (float(o2.open) if (o2 is not None and o2.open)\n                                      else float(o.close) if o is not None else pos["last_mark"])\n                                close_trade(pos, ds + m2 * 60, px, hit)\n                                exit_min = m2\n                                break\n                            if o is None:\n                                px = pos["last_mark"]\n                            elif hit == "SL":\n                                px = float(o.close) if cfg["spot_sl_fill"] == "close" else float(o.low)\n                            else:\n                                px = (float(o.high) if cfg["spot_tp_fill"] == "high"\n                                      else float(o.low) if cfg["spot_tp_fill"] == "low"\n                                      else float(o.close))\n                            close_trade(pos, ds + m * 60, px, hit)\n                            exit_min = m\n                            break\n                elif o is not None:\n                    if sl_prem is not None:\n                        px = prem_fill(level=sl_prem, bar=o, side_is_stop=True)\n                        if px is not None:\n                            close_trade(pos, ds + m * 60, px, "SL")\n                            exit_min = m\n                            break\n                    if tp_prem is not None:\n                        px = prem_fill(level=tp_prem, bar=o, side_is_stop=False)\n                        if px is not None:\n                            close_trade(pos, ds + m * 60, px, "TP")\n                            exit_min = m\n                            break\n                if m >= time_min:\n                    px = float(o.close) if o is not None else pos["last_mark"]\n                    close_trade(pos, ds + m * 60, px, time_reason)\n                    exit_min = m\n                    break\n            else:\n                last_ts = max(ob) if ob else ds + eod_min * 60\n                close_trade(pos, last_ts, pos["last_mark"], "EOD")\n                exit_min = eod_min\n            open_until = exit_min\n\n        if traded:\n            diag["days_traded"] += 1\n\n    src.close()\n    if diag["entries"]:\n        diag["avg_hold_min"] = round(diag["hold_sum"] / diag["entries"], 1)\n        diag["eff_sl_avg_pts"] = round(diag["eff_sl_sum"] / diag["entries"], 2)   # ── STFC_SPOT_20260913 ──\n        diag["eff_tp_avg_pts"] = round(diag["eff_tp_sum"] / diag["entries"], 2)\n    summary = _summarize(trades, diag)\n    write_audit_log(\n        f"[BACKTEST][{strategy_id}] {underlying} {date_from}..{date_to}: "\n        f"{summary[\'total_trades\']} trades, net {summary[\'net_pnl\']:,.0f}, "\n        f"DD {summary[\'max_drawdown\']:,.0f}, exits SL {diag[\'sl_exits\']} / "\n        f"TP {diag[\'tp_exits\']} / TIME {diag[\'time_exits\']} / CANDLE "\n        f"{diag[\'candle_exits\']} / EOD {diag[\'eod_exits\']}, skipped-open "\n        f"{diag[\'sig_dropped_open\']} of {diag[\'signals_total\']} signals"\n    )\n    return {"run_id": str(uuid.uuid4()), "summary": summary,\n            "config": cfg, "trades": trades, "strategy_id": strategy_id}\n\n\ndef _summarize(trades: List[STFCTrade], diag: dict) -> dict:\n    closed = [t for t in trades if t.exit_price is not None]\n    if not closed:\n        s = _empty_summary()\n        s["diag_stfc"] = diag\n        return s\n    eq = peak = mdd = 0.0\n    for t in sorted(closed, key=lambda x: (x.exit_ts or 0, x.entry_ts or 0)):\n        eq += t.net_pnl\n        peak = max(peak, eq)\n        mdd = max(mdd, peak - eq)\n    nets = [t.net_pnl for t in closed]\n    wins = sum(1 for n in nets if n > 0)\n    net = sum(nets)\n    if abs(net) > 1e-9:\n        for k in ("sl", "tp", "time", "candle", "eod"):\n            diag[f"{k}_pnl_share_pct"] = round(100.0 * diag[f"{k}_pnl_gross"] / net, 1)\n    return {\n        "total_trades": len(closed), "wins": wins,\n        "losses": sum(1 for n in nets if n < 0),\n        "win_rate": round(100.0 * wins / len(closed), 2),\n        "gross_pnl": round(sum(t.pnl for t in closed), 2),\n        "total_charges": round(sum(t.charges for t in closed), 2),\n        "net_pnl": round(net, 2), "max_drawdown": round(mdd, 2),\n        "ambiguous_fills": 0,\n        "diag_stfc": diag,\n    }\n'
TEST_SRC = '# backend/app/backtest/stfc/test_stfc_runner_sim.py\n#\n# ── STFC_OPT_20260913 ── behavioural simulation suite. Standalone:\n#   cd backend && python3 app/backtest/stfc/test_stfc_runner_sim.py\n# Part 1 exercises the pure engine; part 2 checks SuperTrend parity with the\n# Crypto Lab implementation on the same random bars; part 3 runs the whole\n# runner against a synthetic corpus and checks fill/exit/overlap invariants.\n\nfrom __future__ import annotations\n\nimport os\nimport random\nimport sqlite3\nimport sys\nimport tempfile\nfrom datetime import date, datetime, timedelta\n\nHERE = os.path.dirname(os.path.abspath(__file__))\nBACKEND = os.path.abspath(os.path.join(HERE, "..", "..", ".."))\nsys.path.insert(0, HERE)\nsys.path.insert(0, BACKEND)\n\nfrom stfc_v1_engine import (                     # noqa: E402\n    StfcBar, SuperTrend, resample_session, session_signals, prem_level,\n    prem_fill, spot_level, spot_breached, strike_step, atm_strike, SESSION_OPEN_MIN)\n\nIST = 5 * 3600 + 30 * 60\nFAILS = []\n\n\ndef check(name: str, ok: bool, note: str = "") -> None:\n    print(f"  {\'PASS\' if ok else \'FAIL\'}  {name}"\n          f"{(\'  — \' + note) if (note and not ok) else \'\'}")\n    if not ok:\n        FAILS.append(name)\n\n\ndef ds_for(d: date) -> int:\n    return int((datetime(d.year, d.month, d.day)\n                - datetime(1970, 1, 1)).total_seconds()) - IST\n\n\ndef _d(ts: int) -> date:\n    return (datetime(1970, 1, 1) + timedelta(seconds=ts + IST)).date()\n\n\ndef m1(ds: int, minute: int, o, h, l, c) -> StfcBar:\n    """1m bar by minute offset from 09:15 (0 = 09:15)."""\n    return StfcBar(ds + (SESSION_OPEN_MIN + minute) * 60, o, h, l, c)\n\n\nDS = ds_for(date(2026, 1, 5))\n\n# ═════════════════════════════════════ 1. engine ═════════════════════════\nprint("── engine: resample ──")\nraw = [m1(DS, k, 100 + k, 105 + k, 95 + k, 101 + k) for k in range(7)]\nb3 = resample_session(raw, day_start_epoch=DS, tf_minutes=3)\ncheck("3m buckets from 09:15", [(b.ts - DS) // 60 for b in b3] == [555, 558, 561])\ncheck("bucket OHLC", b3[0].open == 100 and b3[0].high == 107 and b3[0].low == 95 and b3[0].close == 103)\ncheck("end_min recorded", [b.end_min for b in b3] == [557, 560, 563])\npre = [StfcBar(DS + 9 * 3600 * 1, 1, 1, 1, 1)]           # 09:00, pre-open\ncheck("pre-open bars ignored", len(resample_session(pre + raw, day_start_epoch=DS, tf_minutes=3)) == 3)\n\nprint("── engine: supertrend invariants ──")\nrandom.seed(7)\npx = 100.0\nbars = []\nfor i in range(400):\n    o = px\n    c = px + random.uniform(-2, 2)\n    h = max(o, c) + random.uniform(0, 1.5)\n    l = min(o, c) - random.uniform(0, 1.5)\n    bars.append(StfcBar(i * 180, o, h, l, c))\n    px = c\nst = SuperTrend(10, 2.0)\nout = [st.update(b) for b in bars]\ncheck("ATR na for first len-1 bars", all(out[i][1] is None for i in range(9)) and out[9][1] == 1)\nok = True\nfor i in range(10, 400):\n    line, d = out[i]\n    if d == -1 and bars[i].close < line - 1e-9:\n        ok = False\n    if d == 1 and bars[i].close > line + 1e-9:\n        ok = False\ncheck("direction consistent with price/band", ok)\nflips = sum(1 for i in range(10, 400) if out[i][1] != out[i - 1][1])\ncheck("plausible flip count", 3 <= flips <= 120, str(flips))\n\nprint("── engine: setup machine ──")\n\n\ndef run_seq(seq, direction="BOTH"):\n    bs, ds_ = [], []\n    for i, (d, col) in enumerate(seq):\n        c = 101 if col == "g" else 99 if col == "r" else 100\n        bs.append(StfcBar(DS + (SESSION_OPEN_MIN + 3 * i) * 60, 100, 102, 98, c, SESSION_OPEN_MIN + 3 * i + 2))\n        ds_.append(d)\n    diag = {}\n    sig = session_signals(bs, ds_, direction=direction, diag=diag)\n    return [(s.bar_index, s.side, s.flip_index, s.confirm_index) for s in sig], diag\n\n\nsig, dg = run_seq([(1, "r"), (1, "g"), (-1, "g"), (-1, "r"), (-1, "r"), (-1, "g"), (-1, "r"), (-1, "g"), (-1, "g")])\ncheck("flip C1 ignored, red red GREEN confirms, trade next bar (CE)", sig == [(6, "CE", 2, 5)], str(sig))\nsig, dg = run_seq([(1, "r"), (-1, "g"), (1, "g"), (1, "r"), (1, "g")])\ncheck("flip back resets pending → PE setup", sig == [(4, "PE", 2, 3)], str(sig))\nsig, dg = run_seq([(1, "r"), (-1, "g"), (1, "g"), (1, "r"), (1, "g")], direction="UP")\ncheck("direction UP gates down flips", sig == [])\nsig, dg = run_seq([(1, "r"), (-1, "g"), (-1, "g"), (1, "r"), (1, "r"), (1, "g")])\ncheck("trade on a flip bar still executes; new setup starts there", sig == [(3, "CE", 1, 2), (5, "PE", 3, 4)], str(sig))\nsig, dg = run_seq([(1, "r"), (-1, "g"), (-1, "d"), (-1, "d")])\ncheck("doji never confirms", sig == [])\nsig, dg = run_seq([(1, "r"), (-1, "g"), (-1, "g")])\ncheck("arm on the last bar is lost (no overnight carry) and counted", sig == [] and dg.get("arm_lost_eod") == 1)\nsig, dg = run_seq([(None, "g"), (None, "g"), (1, "g"), (-1, "g"), (-1, "g"), (-1, "g")])\ncheck("warm-up None directions never flip", sig == [(5, "CE", 3, 4)] and dg.get("flips_up") == 1, str(sig))\n\nprint("── engine: levels / fills / strikes ──")\ncheck("prem_level pct stop", prem_level(100, "pct", 20, is_stop=True) == 80)\ncheck("prem_level abs target", prem_level(100, "abs", 15, is_stop=False) == 115)\ncheck("prem_level off", prem_level(100, "off", 15, is_stop=False) is None and prem_level(100, "pct", 0, is_stop=True) is None)\ncheck("prem_level floors at 0.05", prem_level(1.0, "abs", 5, is_stop=True) == 0.05)\nB = StfcBar(0, 100, 106, 94, 101)\ncheck("stop fill at level", prem_fill(level=95, bar=B, side_is_stop=True) == 95)\ncheck("stop gapped through → open", prem_fill(level=101, bar=StfcBar(0, 99, 100, 98, 99), side_is_stop=True) == 99)\ncheck("target untouched → None", prem_fill(level=107, bar=B, side_is_stop=False) is None)\nprint("── engine: spot levels / breach (STFC_SPOT_20260913) ──")\ncheck("CE stop below, target above", spot_level(24000, "CE", "abs", 30, is_stop=True) == 23970 and spot_level(24000, "CE", "abs", 60, is_stop=False) == 24060)\ncheck("PE mirrored", spot_level(24000, "PE", "abs", 30, is_stop=True) == 24030 and spot_level(24000, "PE", "abs", 60, is_stop=False) == 23940)\ncheck("pct of entry spot", abs(spot_level(24000, "CE", "pct", 0.1, is_stop=True) - 23976) < 1e-9)\nSB = StfcBar(0, 24000, 24040, 23965, 24010)\ncheck("CE stop touch via low", spot_breached("CE", 23970, SB, is_stop=True) and not spot_breached("CE", 23960, SB, is_stop=True))\ncheck("CE stop close-trigger ignores the wick", not spot_breached("CE", 23970, SB, is_stop=True, trigger="close") and spot_breached("CE", 24010, SB, is_stop=True, trigger="close"))\ncheck("CE target touch via high", spot_breached("CE", 24035, SB, is_stop=False) and not spot_breached("CE", 24045, SB, is_stop=False))\ncheck("PE stop via high, PE target via low", spot_breached("PE", 24035, SB, is_stop=True) and spot_breached("PE", 23970, SB, is_stop=False))\ncheck("strike step inferred", strike_step([24000, 24050, 24100, None]) == 50 and strike_step([50000, 50100]) == 100)\ncheck("atm rounding", atm_strike(24026, 50) == 24050 and atm_strike(24024, 50) == 24000)\n\n# ═════════════════════════════ 2. parity with crypto engine ══════════════\nprint("── parity: SuperTrend vs crypto_stfc_engine ──")\ntry:\n    import types\n    import importlib.util\n    stub = types.ModuleType("app.backtest.crypto.delta_corpus")\n    stub.db = lambda: None\n    stub.IST = None\n    saved = sys.modules.get("app.backtest.crypto.delta_corpus")\n    sys.modules["app.backtest.crypto.delta_corpus"] = stub\n    spec = importlib.util.spec_from_file_location(\n        "crypto_stfc_engine_parity",\n        os.path.join(BACKEND, "app", "backtest", "crypto", "crypto_stfc_engine.py"))\n    CE = importlib.util.module_from_spec(spec)\n    sys.modules["crypto_stfc_engine_parity"] = CE\n    spec.loader.exec_module(CE)\n    if saved is not None:\n        sys.modules["app.backtest.crypto.delta_corpus"] = saved\n    cb = [dict(ts=b.ts, o=b.open, h=b.high, l=b.low, c=b.close, subs=[], i0=i) for i, b in enumerate(bars)]\n    ref = CE.supertrend(cb, 10, 2.0)\n    same = all((ref[i][1] == out[i][1]) and\n               (ref[i][0] is None and out[i][0] is None or abs((ref[i][0] or 0) - (out[i][0] or 0)) < 1e-9)\n               for i in range(400))\n    check("400-bar SuperTrend lines and directions identical to the Crypto Lab engine", same)\nexcept Exception as e:                                     # crypto engine absent → skip, not fail\n    print(f"  SKIP  crypto engine parity ({e!r})")\n\n# ═════════════════════════════ 3. runner e2e ═════════════════════════════\nprint("── runner: synthetic corpus ──")\ntry:\n    from backtest_stfc_runner import run_stfc_backtest, _merge_cfg, DEFAULTS   # noqa: E402\n    from app.backtest.engine.expiry_calendar import expected_expiry_for_day  # noqa: E402\n    from app.utils.market_hours import is_trading_day                         # noqa: E402\nexcept Exception as e:\n    print(f"  SKIP  runner e2e (app tree unavailable: {e!r})")\n    if FAILS:\n        print("FAILED:", FAILS)\n        sys.exit(1)\n    print("ALL PASS")\n    sys.exit(0)\n\nDDL = """CREATE TABLE backtest_candles_1m(instrument_token INTEGER,ts INTEGER,underlying TEXT,\ntradingsymbol TEXT,instrument_type TEXT,strike REAL,expiry TEXT,open REAL,high REAL,low REAL,\nclose REAL,volume INTEGER,oi INTEGER);\nCREATE INDEX i1 ON backtest_candles_1m(tradingsymbol,ts);\nCREATE INDEX i2 ON backtest_candles_1m(underlying,expiry,ts);\nCREATE INDEX i3 ON backtest_candles_1m(underlying,instrument_type,ts);"""\n\n\ndef build_corpus(path: str, days: list, seed: int = 11) -> dict:\n    """Random-walk NIFTY spot (0.02%/min sigma) + synthetic weekly chain:\n    CE = max(spot-K,0)+time_value, PE mirror; time value decays with the\n    minute so 0DTE-like behaviour exists. Returns {day: expiry}."""\n    random.seed(seed)\n    conn = sqlite3.connect(path)\n    conn.executescript(DDL)\n    rows = []\n    exp_by_day = {}\n    spot = 24000.0\n    for d in days:\n        ds = ds_for(d)\n        exp = expected_expiry_for_day(d).isoformat()\n        exp_by_day[d] = exp\n        strikes = [24000 + 50 * k for k in range(-12, 13)]\n        minute_spot = []\n        for m in range(SESSION_OPEN_MIN, 15 * 60 + 30):\n            o = spot\n            c = spot * (1 + random.gauss(0, 0.0002))\n            h = max(o, c) * (1 + abs(random.gauss(0, 0.00008)))\n            l = min(o, c) * (1 - abs(random.gauss(0, 0.00008)))\n            ts = ds + m * 60\n            rows.append((1, ts, "NIFTY", "NIFTY", "SPOT", None, None, o, h, l, c, 0, 0))\n            minute_spot.append((ts, o, h, l, c, m))\n            spot = c\n        for K in strikes:\n            for side in ("CE", "PE"):\n                sym = f"NIFTY{exp.replace(\'-\', \'\')}{K}{side}"\n                for (ts, o, h, l, c, m) in minute_spot:\n                    tv = 60.0 * (1 - (m - SESSION_OPEN_MIN) / 800.0)\n                    def px(s):\n                        return round(max(s - K, 0) + tv, 2) if side == "CE" else round(max(K - s, 0) + tv, 2)\n                    rows.append((2, ts, "NIFTY", sym, side, float(K), exp,\n                                 px(o), max(px(h), px(l), px(o), px(c)), min(px(h), px(l), px(o), px(c)), px(c), 100, 100))\n    conn.executemany("INSERT INTO backtest_candles_1m VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?)", rows)\n    conn.commit()\n    conn.close()\n    return exp_by_day\n\n\ntmpdir = tempfile.mkdtemp()\ndbp = os.path.join(tmpdir, "bt.db")\nall_days = []\nd = date(2026, 1, 1)\nwhile len(all_days) < 8:\n    if is_trading_day(d):\n        all_days.append(d)\n    d += timedelta(days=1)\nexp_by_day = build_corpus(dbp, all_days)\nwarm = all_days[:3]\nrun_days = all_days[3:]\nos.environ.setdefault("SCALP_LOT_SIZE_OFFLINE", "1")\n\n\ndef run(cfg, **kw):\n    r = run_stfc_backtest(db_path=dbp, strategy_id="STFC_V1", underlying="NIFTY",\n                          date_from=run_days[0], date_to=run_days[-1],\n                          config_override=cfg, **kw)\n    return r\n\n\ndef invariants(r, cfg, label):\n    cfgm = _merge_cfg(cfg)\n    tf = cfgm["timeframe_minutes"]\n    trades = r["trades"]\n    diag = r["summary"]["diag_stfc"]\n    ok_all = True\n    notes = []\n    last_exit = {}\n    for t in trades:\n        ds = ds_for(_d(t.entry_ts))\n        emin = (t.entry_ts - ds) // 60\n        if (emin - SESSION_OPEN_MIN) % tf != 0:\n            ok_all = False; notes.append(f"entry not on tf grid {emin}")\n        if t.exit_ts < t.entry_ts:\n            ok_all = False; notes.append("exit before entry")\n        if t.exit_reason not in ("SL", "TP", "TIME", "CANDLE", "EOD"):\n            ok_all = False; notes.append(f"bad reason {t.exit_reason}")\n        if cfgm["exit_basis"] == "premium":\n            if t.exit_reason == "SL" and t.exit_price > t.sl + 1e-9:\n                ok_all = False; notes.append("SL fill above level")\n            if t.exit_reason == "TP" and t.exit_price < t.tp - 1e-9:\n                ok_all = False; notes.append("TP fill below level")\n        xmin = (t.exit_ts - ds) // 60\n        if t.exit_reason == "CANDLE" and xmin != emin + tf - 1:\n            ok_all = False; notes.append(f"CANDLE exit minute {xmin} != {emin + tf - 1}")\n        if t.exit_reason == "TIME" and t.hold_min != cfgm["hold_minutes"]:\n            ok_all = False; notes.append(f"TIME hold {t.hold_min}")\n        if t.exit_reason == "EOD" and xmin != 15 * 60 + 20:\n            ok_all = False; notes.append(f"EOD minute {xmin}")\n        if cfgm["direction"] == "UP" and t.instrument_type != "CE":\n            ok_all = False; notes.append("UP produced PE")\n        if ds in last_exit and t.entry_ts <= last_exit[ds]:\n            ok_all = False; notes.append("overlapping positions")\n        last_exit[ds] = t.exit_ts\n        if abs(t.net_pnl - (t.pnl - t.charges)) > 0.011:\n            ok_all = False; notes.append("net != gross - charges")\n    acc = (diag["entries"] + diag["sig_dropped_open"] + diag["sig_dropped_budget"]\n           + diag["sig_dropped_block_time"] + diag["sig_no_spot_bar"]\n           + diag["sig_no_candidate"] + diag["sig_no_fill"] + diag["sig_band_reject"])\n    if acc != diag["signals_total"]:\n        ok_all = False; notes.append(f"signal accounting {acc} != {diag[\'signals_total\']}")\n    if diag["entries"] != len(trades):\n        ok_all = False; notes.append("entries != trades")\n    check(f"{label}: invariants over {len(trades)} trades", ok_all, "; ".join(notes[:4]))\n    return trades, diag\n\n\nbase = dict(DEFAULTS)\nbase.update(timeframe_minutes=3, st_len=10, st_mult=2.0, exit_basis="premium", sl_mode="pct", sl_value=20,\n            tp_mode="pct", tp_value=30, exit_mode="candle")\nr = run(base)\ncheck("run completes (not aborted)", not r.get("aborted"), str(r.get("reason")))\ntrades, diag = invariants(r, base, "candle mode")\ncheck("warm-up consumed prior sessions", diag["warmup_bars"] > 0)\ncheck("some trades and signals", len(trades) > 0 and diag["signals_total"] >= len(trades))\ncheck("ATM strike selection", all(t.strike == atm_strike(t.entry_spot, 50) for t in trades if "FB" not in t.condition))\ncheck("entry fill = option 1m open at entry minute", True)   # by construction of the runner; covered via sqlite check below\nconn = sqlite3.connect(dbp)\nok = True\nfor t in trades[:20]:\n    row = conn.execute("SELECT open FROM backtest_candles_1m WHERE tradingsymbol=? AND ts=?",\n                       (t.tradingsymbol, t.entry_ts)).fetchone()\n    if row is None or abs(row[0] - t.entry_price) > 0.011:\n        ok = False\nconn.close()\ncheck("entry_price equals the contract\'s 1m open at entry_ts", ok)\ncheck("candle-mode exits are CANDLE/SL/TP only", diag["time_exits"] == 0 and diag["eod_exits"] == 0)\ncheck("pnl shares sum to ~100%", abs(sum(diag.get(f"{k}_pnl_share_pct", 0) for k in ("sl", "tp", "time", "candle", "eod")) - 100) < 1.0\n      if abs(r["summary"]["net_pnl"]) > 1 else True)\n\nmins = dict(base, exit_mode="minutes", hold_minutes=60, sl_mode="off", tp_mode="off")\nr2 = run(mins)\ntrades2, diag2 = invariants(r2, mins, "minutes mode, no SL/TP")\ncheck("all exits TIME (or EOD near close)", diag2["sl_exits"] == 0 and diag2["tp_exits"] == 0 and diag2["time_exits"] > 0 and diag2["candle_exits"] == 0)\ncheck("holds skip overlapping signals", diag2["sig_dropped_open"] > 0)\ncheck("fewer entries than candle mode (skips)", len(trades2) <= len(trades))\n\nup = dict(base, direction="UP")\nr3 = run(up)\ntrades3, diag3 = invariants(r3, up, "direction UP")\ncheck("UP → CE only, pe_entries 0", diag3["pe_entries"] == 0 and diag3["flips_dn"] > 0)\n\noff = dict(base, strike_offset=2)\nr4 = run(off)\ntrades4, _ = invariants(r4, off, "strike offset +2")\ncheck("offset +2 OTM applied per side", all(\n    (t.strike == atm_strike(t.entry_spot, 50) + 100) if t.instrument_type == "CE"\n    else (t.strike == atm_strike(t.entry_spot, 50) - 100) for t in trades4 if "FB" not in t.condition))\n\ncap = dict(base, max_trades_per_day=2)\nr5 = run(cap)\ntrades5, diag5 = invariants(r5, cap, "max 2/day")\nper_day = {}\nfor t in trades5:\n    per_day[_d(t.entry_ts)] = per_day.get(_d(t.entry_ts), 0) + 1\ncheck("max_trades_per_day respected", all(v <= 2 for v in per_day.values()) and diag5["sig_dropped_budget"] > 0)\n\nblk = dict(base, entry_block_time="10:00", eod_square_off="10:30")\nr6 = run(blk)\ntrades6, diag6 = invariants(r6, blk, "block 10:00 / eod 10:30")\ncheck("no entries at/after block time", all((t.entry_ts - ds_for(_d(t.entry_ts))) // 60 < 600 for t in trades6))\n\ndte = dict(base, dte_lot_mult="0:0")\nr7 = run(dte)\ntrades7, diag7 = invariants(r7, dte, "dte_lot_mult 0:0")\ncheck("expiry-day sessions skipped via DTE mult", diag7["dte_skipped_days"] >= 1 or diag7["dte_unknown_days"] >= 1)\n\nskip = dict(base, skip_expiry_day=True)\nr8 = run(skip)\ncheck("skip_expiry_day counts", r8["summary"]["diag_stfc"]["days_skipped_expiry"] >= 1)\n\nprint("── runner: spot basis (STFC_SPOT_20260913) ──")\n\n\ndef spot_ok(trades, cfgm, fill_sl, fill_tp, trig):\n    """Every SL/TP exit must have a spot bar breaching its level in the exit\n    minute (touch) or the previous minute (close-trigger, fills next open),\n    and the option fill must be the configured print."""\n    conn = sqlite3.connect(dbp)\n    good = True\n    notes = []\n    for t in trades:\n        if t.exit_reason not in ("SL", "TP"):\n            continue\n        ds = ds_for(_d(t.entry_ts))\n        xm = t.exit_ts if trig == "touch" else t.exit_ts - 60\n        sb = conn.execute("SELECT open,high,low,close FROM backtest_candles_1m WHERE underlying=\'NIFTY\' AND instrument_type=\'SPOT\' AND ts=?", (xm,)).fetchone()\n        ob = conn.execute("SELECT open,high,low,close FROM backtest_candles_1m WHERE tradingsymbol=? AND ts=?", (t.tradingsymbol, t.exit_ts)).fetchone()\n        if sb is None or ob is None:\n            good = False; notes.append("missing bars"); continue\n        bar = StfcBar(xm, *sb)\n        lvl = t.sl if t.exit_reason == "SL" else t.tp\n        if not spot_breached(t.instrument_type, lvl, bar, is_stop=(t.exit_reason == "SL"), trigger=trig):\n            good = False; notes.append(f"{t.exit_reason} without breach at {xm}")\n        want = (ob[0] if trig == "close" else\n                {"low": ob[2], "close": ob[3], "high": ob[1]}[fill_sl if t.exit_reason == "SL" else fill_tp])\n        if abs(t.exit_price - want) > 0.011:\n            good = False; notes.append(f"{t.exit_reason} fill {t.exit_price} != {want}")\n    conn.close()\n    return good, "; ".join(notes[:3])\n\n\nsp = dict(base, exit_basis="spot", sl_mode="abs", sl_value=15, tp_mode="abs", tp_value=30, exit_mode="minutes", hold_minutes=30)\nr9 = run(sp)\ncheck("spot run completes", not r9.get("aborted"), str(r9.get("reason")))\ntrades9, diag9 = invariants(r9, sp, "spot basis abs 15/30, touch")\ncheck("spot basis produces SL and TP exits", diag9["sl_exits"] > 0 and diag9["tp_exits"] > 0 and diag9["exit_basis"] == "spot")\ncheck("trade sl/tp carry SPOT levels (CE below/above entry_spot)", all(\n    (t.sl < t.entry_spot < t.tp) if t.instrument_type == "CE" else (t.tp < t.entry_spot < t.sl) for t in trades9))\ncheck("effective distances reported", abs(diag9["eff_sl_avg_pts"] - 15) < 1e-6 and abs(diag9["eff_tp_avg_pts"] - 30) < 1e-6)\nok, note = spot_ok(trades9, sp, "low", "close", "touch")\ncheck("touch: SL books at option LOW, TP at option CLOSE, each with a real spot breach", ok, note)\n\nsp2 = dict(sp, spot_sl_fill="close", spot_tp_fill="high")\ntrades10 = run(sp2)["trades"]\nok, note = spot_ok(trades10, sp2, "close", "high", "touch")\ncheck("fill selects honoured (close / high)", ok, note)\nnet_low = sum(t.net_pnl for t in trades9); net_hi = sum(t.net_pnl for t in trades10)\ncheck("optimistic fills never worse than pessimistic", net_hi >= net_low - 1e-6, f"{net_hi} vs {net_low}")\n\nsp3 = dict(sp, spot_sl_trigger="close")\nr11 = run(sp3)\ntrades11, diag11 = invariants(r11, sp3, "spot basis, close trigger")\nok, note = spot_ok(trades11, sp3, "low", "close", "close")\ncheck("close trigger: breach on the 1m close, fill at NEXT minute\'s option open", ok, note)\n\nspp = dict(sp, sl_mode="pct", sl_value=0.1, tp_mode="pct", tp_value=0.3)\nr12 = run(spp)\ntrades12, diag12 = invariants(r12, spp, "spot basis pct 0.1/0.3")\ncheck("pct distances ≈ 24 / 72 pts on a 24k index", 20 < diag12["eff_sl_avg_pts"] < 28 and 60 < diag12["eff_tp_avg_pts"] < 84)\n\nlegacy = {k: v for k, v in base.items() if k != "exit_basis"}\ncheck("saved v1 config (no exit_basis) reproduces as PREMIUM basis", _merge_cfg(legacy)["exit_basis"] == "premium")\ncheck("blank override takes the new default (spot)", _merge_cfg({})["exit_basis"] == "spot")\n\nprint("── runner: config guards (abort, never run) ──")\nfor bad, why in ((dict(base, sl_mode="pct", sl_value=150), "pct SL > 100 looks like rupees"),\n                 (dict(base, entry_block_time="15:25", eod_square_off="15:20"), "block after eod"),\n                 (dict(base, exit_mode="minutes", hold_minutes=400), "hold > 375"),\n                 (dict(base, timeframe_minutes=90), "tf 90"),\n                 (dict(base, premium_min=200, premium_max=100), "band inverted"),\n                 (dict(base, exit_basis="spot", sl_mode="pct", sl_value=20), "spot pct 20 looks like a premium %"),\n                 (dict(base, exit_basis="spot", tp_mode="abs", tp_value=0.3), "spot abs 0.3 pts looks like pct")):\n    rb = run(bad)\n    check(f"abort: {why}", rb.get("aborted") is True and rb["run_id"] is None)\n\ncanc = run(base, cancel_cb=lambda: True)\ncheck("cancel_cb stops before trading", canc["summary"]["total_trades"] == 0 and not canc.get("aborted"))\n\nprog = []\nrun(base, progress_cb=prog.append)\ncheck("progress callback per day", len(prog) == len(run_days) and prog[-1]["day"] == len(run_days))\n\nif FAILS:\n    print("FAILED:", FAILS)\n    sys.exit(1)\nprint("ALL PASS")\n'

