PF_OLD = '''  p.push((cfg.sl_mode || "off") === "off" ? "SLoff" : `SL${cfg.sl_mode === "pct" ? "P" : "A"}${cfg.sl_value}`);
  p.push((cfg.tp_mode || "off") === "off" ? "TPoff" : `TP${cfg.tp_mode === "pct" ? "P" : "A"}${cfg.tp_value}`);
'''
PF_NEW = '''  const b = cfg.exit_basis === "spot" ? "s" : "";   // ── STFC_SPOT_20260913 ── sSL/sTP = spot-basis levels
  p.push((cfg.sl_mode || "off") === "off" ? "SLoff" : `${b}SL${cfg.sl_mode === "pct" ? "P" : "A"}${cfg.sl_value}`);
  p.push((cfg.tp_mode || "off") === "off" ? "TPoff" : `${b}TP${cfg.tp_mode === "pct" ? "P" : "A"}${cfg.tp_value}`);
  if (b && cfg.spot_sl_trigger === "close") p.push("trigC");
  if (b && cfg.spot_sl_trigger !== "close" && (cfg.spot_sl_fill || "low") !== "low") p.push(`slF${cfg.spot_sl_fill}`);
  if (b && cfg.spot_sl_trigger !== "close" && (cfg.spot_tp_fill || "close") !== "close") p.push(`tpF${cfg.spot_tp_fill}`);
'''
# ─── SweepBuilder: hint text for the SL/TP axes
SW_OLD = '''  { key: "stfc_sl", label: "STFC SL value (unit = form's SL mode)", strategies: [STFC],
    hint: "10, 20, 30  ·  0 = off", parse: _num,'''
SW_NEW = '''  { key: "stfc_sl", label: "STFC SL value (unit = form's basis + SL mode)", strategies: [STFC],
    hint: "spot %: 0.05, 0.1, 0.15  ·  spot pts: 15, 25, 40  ·  premium %: 10, 20, 30  ·  0 = off", parse: _num,'''
SW2_OLD = '''  { key: "stfc_tp", label: "STFC TP value (unit = form's TP mode)", strategies: [STFC],
    hint: "20, 30, 50  ·  0 = off", parse: _num,'''
SW2_NEW = '''  { key: "stfc_tp", label: "STFC TP value (unit = form's basis + TP mode)", strategies: [STFC],
    hint: "spot %: 0.2, 0.3, 0.5  ·  spot pts: 40, 60, 100  ·  premium %: 20, 30, 50  ·  0 = off", parse: _num,'''



def die(msg):
    print("ABORT:", msg); sys.exit(1)


def read(p):
    with open(p, encoding="utf-8") as f:
        return f.read()


def replace_n(src, old, new, label, n=1):
    c = src.count(old)
    if c != n:
        die(f"anchor '{label}' count={c} (expected {n})")
    return src.replace(old, new)


def compile_gate(text, name):
    with tempfile.NamedTemporaryFile("w", suffix=".py", delete=False, encoding="utf-8") as f:
        f.write(text); tmp = f.name
    try:
        py_compile.compile(tmp, doraise=True)
    except py_compile.PyCompileError as e:
        die(f"py_compile failed for {name}: {e}")
    finally:
        os.unlink(tmp)


P_PKG = os.path.join(BACKEND, "app", "backtest", "stfc")
P_ENGINE = os.path.join(P_PKG, "stfc_v1_engine.py")
P_RUNNER = os.path.join(P_PKG, "backtest_stfc_runner.py")
P_TEST = os.path.join(P_PKG, "test_stfc_runner_sim.py")
P_BT = os.path.join(FRONTEND, "src", "pages", "Backtest.jsx")
P_PF = os.path.join(FRONTEND, "src", "pages", "backtest", "paramFormat.js")
P_SW = os.path.join(FRONTEND, "src", "pages", "backtest", "SweepBuilder.jsx")
ALL = [P_ENGINE, P_RUNNER, P_TEST, P_BT, P_PF, P_SW]

for p in ALL:
    if not os.path.exists(p):
        die(f"missing {p} — apply {PARENT} first")
    if PARENT not in read(p):
        die(f"parent fence {PARENT} not found in {p}")
    if FENCE in read(p):
        die(f"{FENCE} already present in {p}")
try:
    st = subprocess.run(["git", "status", "--porcelain", "--"] + ALL, capture_output=True, text=True, cwd=ROOT)
    dirty = [l for l in st.stdout.splitlines() if l.strip() and not l.startswith("??")]
    if dirty:
        die("uncommitted changes on files this script patches (commit or stash first):\n  " + "\n  ".join(dirty))
except FileNotFoundError:
    print("git not found — drift check skipped")

bt = read(P_BT)
bt = replace_n(bt, BT_STATE_OLD, BT_STATE_NEW, "bt state")
bt = replace_n(bt, BT_LS_OLD, BT_LS_NEW, "bt ls json")
bt = replace_n(bt, BT_LSDEPS_OLD, BT_LSDEPS_NEW, "bt ls deps")
bt = replace_n(bt, BT_BUILD_OLD, BT_BUILD_NEW, "bt buildConfig")
bt = replace_n(bt, BT_DEPS_OLD, BT_DEPS_NEW, "bt deps")
bt = replace_n(bt, BT_FORM_OLD, BT_FORM_NEW, "bt form")
bt = replace_n(bt, BT_SUMMARY_OLD, BT_SUMMARY_NEW, "bt summary text")
bt = replace_n(bt, BT_DESC_OLD, BT_DESC_NEW, "bt describeConfig")
pf = replace_n(read(P_PF), PF_OLD, PF_NEW, "paramFormat")
sw = replace_n(read(P_SW), SW_OLD, SW_NEW, "sweep sl hint")
sw = replace_n(sw, SW2_OLD, SW2_NEW, "sweep tp hint")
for text, name in ((ENGINE_SRC, "engine"), (RUNNER_SRC, "runner"), (TEST_SRC, "test")):
    compile_gate(text, name)
print("py_compile gate: OK (3 files)")

for p in ALL:
    shutil.copy2(p, p + f".bak-{FENCE}")
for p, text in ((P_ENGINE, ENGINE_SRC), (P_RUNNER, RUNNER_SRC), (P_TEST, TEST_SRC),
                (P_BT, bt), (P_PF, pf), (P_SW, sw)):
    with open(p, "w", encoding="utf-8") as f:
        f.write(text)
print("primary tree written (6 files, 6 backups)")

r = subprocess.run([sys.executable, P_TEST], capture_output=True, text=True, cwd=BACKEND)
if r.returncode != 0 or "ALL PASS" not in r.stdout:
    print(r.stdout[-4000:]); print(r.stderr[-2000:])
    die("simulation suite failed — files are written; restore from .bak-" + FENCE + " if needed")
n = r.stdout.count("  PASS")
print(f"simulation suite: ALL PASS ({n} checks)")


def mirror(src_root, dst_root, rel):
    dst = os.path.join(dst_root, rel)
    os.makedirs(os.path.dirname(dst), exist_ok=True)
    shutil.copy2(os.path.join(src_root, rel), dst)


if os.path.isdir(DUAL_BACKEND):
    for rel in ("app/backtest/stfc/stfc_v1_engine.py", "app/backtest/stfc/backtest_stfc_runner.py",
                "app/backtest/stfc/test_stfc_runner_sim.py"):
        mirror(BACKEND, DUAL_BACKEND, rel)
    print("dual backend tree synced")
else:
    print("dual backend tree absent (build script rsyncs it) — skipped")
if os.path.isdir(DUAL_FRONTEND):
    for rel in ("src/pages/Backtest.jsx", "src/pages/backtest/paramFormat.js", "src/pages/backtest/SweepBuilder.jsx"):
        mirror(FRONTEND, DUAL_FRONTEND, rel)
    print("dual frontend tree synced")
else:
    print("dual frontend tree absent (build script rsyncs it) — skipped")

esb = None
for cand in (os.path.join(FRONTEND, "node_modules", ".bin", "esbuild"),
             os.path.join(ROOT, "desktop", "node_modules", ".bin", "esbuild"), shutil.which("esbuild")):
    if cand and os.path.exists(cand):
        esb = cand; break
if esb:
    for p in (P_BT, P_PF, P_SW):
        r = subprocess.run([esb, p, "--loader:.jsx=jsx", "--loader:.js=jsx", "--jsx=automatic", "--outfile=/dev/null"],
                           capture_output=True, text=True)
        if r.returncode != 0:
            print(r.stderr); die(f"esbuild failed for {p}")
    print("esbuild: OK (3 frontend files)")
else:
    print("esbuild not found — run `npm run build` in frontend/ to verify")
print(f"\nDONE — {FENCE} applied. Rebuild: ./desktop/build-scalp.sh both")
